#include "ui_fonts.h"

#include <cmath>

#include "icons.h"

// Generated by cmake/embed.cmake from Dear ImGui's misc/fonts folder.
extern const unsigned char FONT_ROBOTO[];
extern const unsigned long FONT_ROBOTO_size;
extern const unsigned char FONT_COUSINE[];
extern const unsigned long FONT_COUSINE_size;

namespace {
UiFonts fonts;

ImFont* addTtf(const unsigned char* data, unsigned long size, float px) {
  ImFontConfig cfg;
  cfg.FontDataOwnedByAtlas = false;  // static data, not to be freed
  cfg.OversampleH = 2;
  cfg.OversampleV = 1;
  cfg.PixelSnapH = true;
  return ImGui::GetIO().Fonts->AddFontFromMemoryTTF((void*)data, (int)size, px, &cfg);
}

ImFont* addPixel(float px) {
  ImFontConfig cfg;
  cfg.SizePixels = px;
  return ImGui::GetIO().Fonts->AddFontDefault(&cfg);
}
}  // namespace

const UiFonts& uiFonts() { return fonts; }

void buildUiFonts(float scale, bool modern) {
  ImFontAtlas* atlas = ImGui::GetIO().Fonts;
  atlas->Clear();
  fonts = UiFonts();
  float pixel = std::round(13.0f * scale), uiPx = pixel, monoPx = pixel, bigPx = std::round(20.0f * scale);
  if (modern) {
    uiPx = std::round(15.0f * scale);
    monoPx = std::round(14.0f * scale);
    bigPx = std::round(22.0f * scale);
    fonts.ui = addTtf(FONT_ROBOTO, FONT_ROBOTO_size, uiPx);
    fonts.mono = addTtf(FONT_COUSINE, FONT_COUSINE_size, monoPx);
    fonts.big = addTtf(FONT_ROBOTO, FONT_ROBOTO_size, bigPx);
    fonts.caption = addTtf(FONT_ROBOTO, FONT_ROBOTO_size, std::round(11.0f * scale));
    fonts.pixel = addPixel(pixel);
  } else {
    fonts.ui = addPixel(pixel);
    fonts.mono = fonts.ui;
    fonts.big = addPixel(bigPx);
    fonts.caption = fonts.ui;
    fonts.pixel = fonts.ui;
  }
  addIconGlyphs(atlas, fonts.ui, uiPx);
  if (fonts.mono != fonts.ui) addIconGlyphs(atlas, fonts.mono, monoPx);
  addIconGlyphs(atlas, fonts.big, bigPx);
  if (fonts.pixel != fonts.ui) addIconGlyphs(atlas, fonts.pixel, pixel);
  atlas->Build();
  drawIconGlyphs(atlas);
  ImGui::GetIO().FontDefault = fonts.ui;
}
